    }

    struct OpenParams {
        uint160 sqrtPriceX96;
        int24 openingTick;
        address token;
        address feeRecipient;
        address quote;
        uint256 tokenAmount;
        address devBuyer;
        uint24 feePpm;
        bool feesToHolders;
    }

    IPoolManager public immutable poolManager;
    FeeEscrow public immutable escrow;
    address public immutable factory;

    mapping(PoolId => Launch) internal _launches;

    modifier onlyPoolManager() {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        _;
    }

    constructor(IPoolManager poolManager_, FeeEscrow escrow_, address factory_) {
        poolManager = poolManager_;
        escrow = escrow_;
        factory = factory_;
    }

    function getLaunch(PoolId poolId) external view returns (Launch memory) {
        return _launches[poolId];
    }

    function currentFee(PoolId poolId) external view returns (uint256) {
        Launch storage l = _launches[poolId];
        if (l.token == address(0)) revert UnknownPool();
        return _feeRate(l.openedAt, l.feePpm);
    }

    function platformFeeFor(uint24 feePpm) public pure returns (uint256) {
        return feePpm >= HIGH_TIER_FROM ? PLATFORM_FEE_HIGH : PLATFORM_FEE_LOW;
    }

    function openLaunch(PoolKey calldata key, OpenParams calldata o) external returns (uint128 liquidity) {
        if (msg.sender != factory) revert NotFactory();
        if (o.feePpm < MIN_FEE || o.feePpm > MAX_FEE) revert BadFee();

        poolManager.initialize(key, o.sqrtPriceX96);

        bool quoteIsCurrency0 = Currency.unwrap(key.currency0) == o.quote;
        int24 tickLower;
        int24 tickUpper;
        if (quoteIsCurrency0) {
            tickLower = _minUsableTick();
            tickUpper = o.openingTick;
            liquidity = LiquidityAmounts.getLiquidityForAmount1(
                TickMath.getSqrtPriceAtTick(tickLower), TickMath.getSqrtPriceAtTick(tickUpper), o.tokenAmount
            );
        } else {
            tickLower = o.openingTick;
            tickUpper = _maxUsableTick();
            liquidity = LiquidityAmounts.getLiquidityForAmount0(
                TickMath.getSqrtPriceAtTick(tickLower), TickMath.getSqrtPriceAtTick(tickUpper), o.tokenAmount
            );
        }

        PoolId poolId = key.toId();
        _launches[poolId] = Launch({
            token: o.token,
            feeRecipient: o.feeRecipient,
            quote: o.quote,
            openedAt: uint40(block.timestamp),
            feePpm: o.feePpm,
            quoteIsCurrency0: quoteIsCurrency0,
            pendingDevBuy: o.devBuyer != address(0),
            feesToHolders: o.feesToHolders,
            devBuyer: o.devBuyer,
            tickLower: tickLower,
            tickUpper: tickUpper,
            liquidity: liquidity
        });

        poolManager.unlock(abi.encode(ACTION_SEED, abi.encode(key, tickLower, tickUpper, liquidity, o.token)));

        emit LaunchOpened(
            poolId,
            o.token,
            o.feeRecipient,
            o.quote,
            o.sqrtPriceX96,
            tickLower,
            tickUpper,
            liquidity,
            o.feePpm,
            o.feesToHolders
        );
    }

    function sweep(address currency) external {
        sweepCurrency(Currency.wrap(currency));
    }

    function sweepCurrency(Currency currency) public {
        uint256 amount = poolManager.balanceOf(address(this), currency.toId());
        if (amount == 0) return;
        poolManager.unlock(abi.encode(ACTION_SWEEP, abi.encode(currency, amount)));
        emit FeesSwept(Currency.unwrap(currency), amount);
    }

    function unlockCallback(bytes calldata data) external onlyPoolManager returns (bytes memory) {
        (uint8 action, bytes memory payload) = abi.decode(data, (uint8, bytes));
        if (action == ACTION_SWEEP) {
            (Currency currency, uint256 amount) = abi.decode(payload, (Currency, uint256));
            poolManager.burn(address(this), currency.toId(), amount);
            poolManager.take(currency, address(escrow), amount);
            return "";
        }

        (PoolKey memory key, int24 tickLower, int24 tickUpper, uint128 liquidity, address token) =
            abi.decode(payload, (PoolKey, int24, int24, uint128, address));

        (BalanceDelta delta,) = poolManager.modifyLiquidity(
            key,
            ModifyLiquidityParams({
                tickLower: tickLower,
                tickUpper: tickUpper,
                liquidityDelta: int256(uint256(liquidity)),
                salt: bytes32(0)
            }),
            ""
        );

        int128 owed = Currency.unwrap(key.currency0) == token ? delta.amount0() : delta.amount1();
        if (owed < 0) {
            uint256 amount = uint256(uint128(-owed));
            poolManager.sync(Currency.wrap(token));
            IERC20(token).safeTransfer(address(poolManager), amount);
            poolManager.settle();
        }
        return "";
    }

    function beforeInitialize(address sender, PoolKey calldata, uint160)
        external
        view
        onlyPoolManager
        returns (bytes4)
    {
        if (sender != address(this)) revert NotSelf();
        return IHooks.beforeInitialize.selector;
    }

    function beforeAddLiquidity(address sender, PoolKey calldata, ModifyLiquidityParams calldata, bytes calldata)
        external
        view
        onlyPoolManager
        returns (bytes4)
    {
        if (sender != address(this)) revert LiquidityLocked();
        return IHooks.beforeAddLiquidity.selector;
    }

    function beforeSwap(address sender, PoolKey calldata key, SwapParams calldata params, bytes calldata)
        external
        onlyPoolManager
        returns (bytes4, BeforeSwapDelta, uint24)
    {
        if (params.amountSpecified >= 0) revert ExactOutputUnsupported();

        Launch storage l = _launches[key.toId()];
        if (l.token == address(0)) revert UnknownPool();

        bool inputIsQuote = params.zeroForOne == l.quoteIsCurrency0;
        if (!inputIsQuote) return (IHooks.beforeSwap.selector, BeforeSwapDeltaLibrary.ZERO_DELTA, 0);

        uint256 amountIn = uint256(-params.amountSpecified);
        uint256 rate = _consumeFeeRate(l, sender);
        uint256 fee = (amountIn * rate) / FEE_DENOMINATOR;
        if (fee == 0) return (IHooks.beforeSwap.selector, BeforeSwapDeltaLibrary.ZERO_DELTA, 0);

        poolManager.mint(address(this), Currency.wrap(l.quote).toId(), fee);
        _credit(l, fee, amountIn);
        _storeBuyFee(fee);

        return (IHooks.beforeSwap.selector, toBeforeSwapDelta(int128(int256(fee)), int128(0)), 0);
    }

    function afterSwap(
        address sender,
        PoolKey calldata key,
        SwapParams calldata params,
        BalanceDelta delta,
        bytes calldata hookData
    ) external onlyPoolManager returns (bytes4, int128) {
        PoolId poolId = key.toId();
        Launch storage l = _launches[poolId];

        (address trader, address referrer, bytes32 comment) = _decodeHookData(hookData, sender);
        bool inputIsQuote = params.zeroForOne == l.quoteIsCurrency0;

        int128 quoteDelta = l.quoteIsCurrency0 ? delta.amount0() : delta.amount1();
        int128 tokenDelta = l.quoteIsCurrency0 ? delta.amount1() : delta.amount0();

        if (inputIsQuote) {
            uint256 amountIn = uint256(-params.amountSpecified);
            uint256 buyFee = _takeBuyFee();
            emit Trade(poolId, trader, referrer, true, amountIn, uint256(uint128(tokenDelta)), buyFee, comment);
            return (IHooks.afterSwap.selector, int128(0));
        }

        uint256 grossOut = uint256(uint128(quoteDelta));
        uint256 rate = _consumeFeeRate(l, sender);
        uint256 sellFee = (grossOut * rate) / FEE_DENOMINATOR;
        if (sellFee > 0) {
            poolManager.mint(address(this), Currency.wrap(l.quote).toId(), sellFee);
            _credit(l, sellFee, grossOut);
        }

        emit Trade(poolId, trader, referrer, false, uint256(uint128(-tokenDelta)), grossOut - sellFee, sellFee, comment);
        return (IHooks.afterSwap.selector, int128(int256(sellFee)));
    }

    function _credit(Launch storage l, uint256 fee, uint256 amount) internal {
        uint24 feePpm = l.feePpm;
        uint256 creatorAmount = (amount * (feePpm - platformFeeFor(feePpm))) / FEE_DENOMINATOR;
        address recipient = l.feeRecipient;
        escrow.credit(l.quote, recipient, creatorAmount, fee - creatorAmount);
        if (l.feesToHolders && creatorAmount > 0) {
            try IHolderDistributor(recipient).notifyFee(creatorAmount) {} catch {}
        }
    }

    function _consumeFeeRate(Launch storage l, address sender) internal returns (uint256) {
        if (l.pendingDevBuy && sender == l.devBuyer && block.timestamp == l.openedAt) {
            l.pendingDevBuy = false;
            return l.feePpm;
        }
        return _feeRate(l.openedAt, l.feePpm);
    }

    function _storeBuyFee(uint256 fee) internal {
        assembly ("memory-safe") {
            tstore(BUY_FEE_SLOT, fee)
        }
    }

    function _takeBuyFee() internal returns (uint256 fee) {
        assembly ("memory-safe") {
            fee := tload(BUY_FEE_SLOT)
            tstore(BUY_FEE_SLOT, 0)
        }
    }

    function _feeRate(uint40 openedAt, uint24 feePpm) internal view returns (uint256) {
        uint256 elapsed = block.timestamp - openedAt;
        if (elapsed >= ANTI_SNIPE_DURATION) return feePpm;
        return LAUNCH_FEE - ((LAUNCH_FEE - feePpm) * elapsed) / ANTI_SNIPE_DURATION;
    }

    function _decodeHookData(bytes calldata hookData, address sender)
        internal
        pure
        returns (address trader, address referrer, bytes32 comment)
    {
        if (hookData.length == 96) {
            (trader, referrer, comment) = abi.decode(hookData, (address, address, bytes32));
            if (trader == address(0)) trader = sender;
        } else {
            trader = sender;
        }
    }

    function _maxUsableTick() internal pure returns (int24) {
        return (TickMath.MAX_TICK / TICK_SPACING) * TICK_SPACING;
    }

    function _minUsableTick() internal pure returns (int24) {
        return -((TickMath.MAX_TICK / TICK_SPACING) * TICK_SPACING);
    }

    function afterInitialize(address, PoolKey calldata, uint160, int24) external pure returns (bytes4) {
        revert HookNotImplemented();
    }

    function afterAddLiquidity(
        address,
        PoolKey calldata,
        ModifyLiquidityParams calldata,
        BalanceDelta,
        BalanceDelta,
        bytes calldata
    ) external pure returns (bytes4, BalanceDelta) {
        revert HookNotImplemented();
    }

    function beforeRemoveLiquidity(address, PoolKey calldata, ModifyLiquidityParams calldata, bytes calldata)
        external
        pure
        returns (bytes4)
    {
        revert HookNotImplemented();
    }

    function afterRemoveLiquidity(
        address,
        PoolKey calldata,
        ModifyLiquidityParams calldata,
        BalanceDelta,
        BalanceDelta,
        bytes calldata
    ) external pure returns (bytes4, BalanceDelta) {
        revert HookNotImplemented();
    }

    function beforeDonate(address, PoolKey calldata, uint256, uint256, bytes calldata) external pure returns (bytes4) {
        revert HookNotImplemented();
    }

    function afterDonate(address, PoolKey calldata, uint256, uint256, bytes calldata) external pure returns (bytes4) {
        revert HookNotImplemented();
    }
}
