pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";

interface IFeeSweeper {
    function sweep(address currency) external;
}

contract FeeEscrow is Ownable2Step {
    using SafeERC20 for IERC20;

    error NotHook();
    error HookAlreadySet();
    error ZeroAddress();
    error NothingToClaim();

    event HookSet(address hook);
    event PlatformRecipientSet(address recipient);
    event Credited(address indexed account, address indexed currency, uint256 amount);
    event Claimed(address indexed account, address indexed currency, address to, uint256 amount);

    address public hook;
    address public platformRecipient;

    mapping(address => mapping(address => uint256)) public claimable;
    mapping(address => uint256) public totalCredited;

    constructor(address owner_, address platformRecipient_) Ownable(owner_) {
        if (platformRecipient_ == address(0)) revert ZeroAddress();
        platformRecipient = platformRecipient_;
    }

    function setHook(address hook_) external onlyOwner {
        if (hook != address(0)) revert HookAlreadySet();
        if (hook_ == address(0)) revert ZeroAddress();
        hook = hook_;
        emit HookSet(hook_);
    }

    function setPlatformRecipient(address recipient) external onlyOwner {
        if (recipient == address(0)) revert ZeroAddress();
        platformRecipient = recipient;
        emit PlatformRecipientSet(recipient);
    }

    function credit(address currency, address creator, uint256 creatorAmount, uint256 platformAmount) external {
        if (msg.sender != hook) revert NotHook();
        if (creatorAmount > 0) {
            claimable[creator][currency] += creatorAmount;
            emit Credited(creator, currency, creatorAmount);
        }
        if (platformAmount > 0) {
            address recipient = platformRecipient;
            claimable[recipient][currency] += platformAmount;
            emit Credited(recipient, currency, platformAmount);
        }
        unchecked {
            totalCredited[currency] += creatorAmount + platformAmount;
        }
    }

    function claim(address currency, address to) external returns (uint256 amount) {
        if (to == address(0)) revert ZeroAddress();
        amount = claimable[msg.sender][currency];
        if (amount == 0) revert NothingToClaim();
        claimable[msg.sender][currency] = 0;
        if (IERC20(currency).balanceOf(address(this)) < amount) {
            IFeeSweeper(hook).sweep(currency);
        }
        IERC20(currency).safeTransfer(to, amount);
        emit Claimed(msg.sender, currency, to, amount);
    }
}
